import{_ as e,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Monthly 2023-02-01","description":"","frontmatter":{"title":"Ceph Developer Monthly 2023-02-01","date":"2023-02-01T00:00:00.000Z","updated":"2023-02-02T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","扩展性","对象存储","块存储","文件系统存储","一致性","去中心化","性能","Bluestore","BlueFS","RocksDB","OSD","MON","MDS","PG","RADOS","librados","libcephfs","cephfs","rbd","radosgw","RGW","RESTful API","认证","授权","加密","损坏码","复制","快照","克隆","虚拟化","云计算","AWS","Azure","Google Cloud","混合云","多云","存储集群","节点","硬盘","SSD","HDD","JBOD","SAN","NAS","网络","网络拓扑","故障域","恢复","弹性","负载均衡","缓存","压缩","去重","分层","性能调整","基准测试","测试","验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Developer_Monthly_2023-02-01.md","filePath":"posts/2023/Ceph_Developer_Monthly_2023-02-01.md","lastUpdated":1780460162000}'),i={name:"posts/2023/Ceph_Developer_Monthly_2023-02-01.md"};function r(s,l,p,n,h,d){return o(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次Ceph开发者月度会议主要讨论了Ceph存储系统的多个关键议题，包括测试失败、性能监控、S3选择功能、逻辑大规模套件开发以及性能计数器JSON输出格式的调整。会议涵盖了问题的识别、解决方案的探讨以及后续行动计划的制定。</p><h4 id="主要议题与讨论" tabindex="-1">主要议题与讨论 <a class="header-anchor" href="#主要议题与讨论" aria-label="Permalink to &quot;主要议题与讨论&quot;">​</a></h4><ol><li><p><strong>测试失败与健康警告</strong></p><ul><li>会议讨论了由健康警告引起的测试失败问题，并分析了相关PR和日志位置的问题。</li><li>会议决定创建一个草稿PR来检查标准错误和正确的日志位置，并计划在实际的RBD API上进行测试。</li></ul></li><li><p><strong>S3选择功能更新</strong></p><ul><li>介绍了S3选择功能，该功能允许客户端将SQL语句推送到存储层，以提高性能和降低成本。</li><li>讨论了与Spark和Trino等分析应用的集成，并计划继续开发和优化S3选择功能。</li></ul></li><li><p><strong>逻辑大规模套件开发</strong></p><ul><li>目标是开发一个逻辑大规模套件，以便在Ceph上运行更多OSD的测试。</li><li>已经完成了零块检测功能的开发，并正在进一步设置逻辑大规模套件。</li></ul></li><li><p><strong>性能计数器JSON输出格式调整</strong></p><ul><li>讨论了是否以及如何调整性能计数器的JSON输出格式。</li><li>决定添加一个新命令<code>dump_counters</code>，同时保持现有命令不变，逐步将计数器迁移到新命令中。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><p><strong>测试失败与健康警告</strong></p><ul><li>在实际的RBD API上测试草稿PR，确保其正确处理标准错误和日志位置。</li></ul></li><li><p><strong>S3选择功能</strong></p><ul><li>继续开发和优化S3选择功能，特别是与Spark和Trino等分析应用的集成。</li></ul></li><li><p><strong>逻辑大规模套件</strong></p><ul><li>完成逻辑大规模套件的设置，并在多OSD环境下进行全面测试。</li></ul></li><li><p><strong>性能计数器JSON输出</strong></p><ul><li>实现新命令<code>dump_counters</code>，并逐步将计数器迁移到新命令中，同时发布相关更新和迁移指南。</li></ul></li></ol><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>会议成功地识别了多个关键问题，并制定了相应的解决方案和后续行动计划。所有参与者都积极参与讨论，确保了决策的全面性和可行性。下一步将按照会议决议执行相关行动，并持续监控进展情况。</p>',9)])])}const c=e(i,[["render",r]]);export{_ as __pageData,c as default};
